                        elif LooseVersion(self.version) >= LooseVersion('11.1'):
                            guesses['MIC_LD_LIBRARY_PATH'] = [
                                os.path.join('lib', 'mic'),
                                os.path.join(self.mkl_basedir, 'lib', 'mic'),
                            ]
                        else:
