        self,
        fg: Optional[Color] = None,
        bg: Optional[Color] = None,
        attr: Optional[Attribute] = None,
    ) -> Tuple[bytes, bytes]:
        start = b""
        if fg:
            start += self._foreground[fg]
        if bg:
            start += self._background[bg]
        if attr:
            for attr_type in Attribute:
                if attr & int(attr_type):
