class MWA_tile_vpat:
    '''
    class for an MWA tile pattern.  By default it uses a short dipole as the element pattern.  You can specify individual element patterns or gains by giving a 16-element array of these quantities.
    '''

    def __init__(self,freq=None,delays=None,gains=None,gain_func=None,delay_func=None,element_patterns=None,pol=None):

        if element_patterns is None:
            element_patterns=short_dipole_vpat()

        if delays is None:
            delays=0.0

        if gains is None:
            gains=1.0

        if pol is None:
            pol='Y'

        if freq is None:
            freq=100.0E6

        self.set_gains(gains)
        self.set_delays(delays)
        self.set_element_patterns(element_patterns)
        self.set_pol(pol)
        self.set_freq(freq)

        if delay_func is None:
            self.delay_func=lambda x,f: x*435E-12
        else:
            self.delay_func=delay_func

        if gain_func is None:
            self.gain_func=lambda x,f: 1.0
        else:
            self.gain_func=gain_func

        dip_sep=1.1
        self.dipole_y=dip_sep*numpy.array([1.5,1.5,1.5,1.5,0.5,0.5,0.5,0.5,-0.5,-0.5,-0.5,-0.5,-1.5,-1.5,-1.5,-1.5])
        self.dipole_x=dip_sep*numpy.array([-1.5,-0.5,0.5,1.5,-1.5,-0.5,0.5,1.5,-1.5,-0.5,0.5,1.5,-1.5,-0.5,0.5,1.5])

    def set_pol(self,pol):
        for pat in self.element_patterns:
            pat.set_pol(pol)

    def set_freq(self,freq):
        self.freq=freq
        for pat in self.element_patterns:
            pat.set_freq(freq)



    def set_delays(self,delays,ideal=True):
        delays=numpy.array(delays)
        if delays.size == 1: 
            delays=numpy.tile(delays,16)
        self.delays=delays
        if self.delays.size !=16:
            raise ValueError('delays must be a 16-element array')

    def set_gains(self,gains,ideal=True):
        gains=numpy.array(gains)
        if gains.size == 1: 
            gains=numpy.tile(gains,16)
        self.gains=gains
        if self.gains.size !=16:
            raise ValueError('gains must be a 16-element array')

    def set_element_patterns(self,element_patterns):
        element_patterns=numpy.array(element_patterns)
        if element_patterns.size == 1:
            element_patterns=numpy.tile(element_patterns,16)
        self.element_patterns=element_patterns
        if self.element_patterns.size !=16:
            raise ValueError('element_patterns must be a 16-element array of functions')


    def calculate(self,theta,phi):

        lam=2.998e8/self.freq
        dy=self.dipole_y
        dx=self.dipole_x

        dphase=2*math.pi*self.freq*(self.delay_func(self.delays,self.freq)) # phase delay (in radians) at each tile

        #for i=0,n_elements(dip_gains)-1 do dip_gains[i]=dip_gains[i]*get_delay_gains(delays[i],freq)
        ff=2*math.pi*1j/lam
        resp=numpy.zeros_like(theta+phi+1j)

        for dipole in range(16):
            resp=resp+self.gain_func(self.delays[dipole],self.freq)*self.gains[dipole]*self.element_patterns[dipole].calculate(theta,phi)*numpy.exp(ff*dy[dipole]*numpy.sin(theta)*numpy.cos(phi)+ff*dx[dipole]*numpy.sin(theta)*numpy.sin(phi)+-1j*dphase[dipole])
        return resp


