        try:
            return int(x)
        except ValueError:
            return 0

    def mk_sym(x):
        s = x.split("(")
        if not len(s) == 2:
            raise Exception("Wrong bracket format: " + str(code))
        return (s[0].strip(),int0(s[1]))

    symbols = map(mk_sym, termnums)

    righthand = [(symbols, pvalue)]

    return {lefthand: righthand}

