class BlobField(six.with_metaclass(models.SubfieldBase, models.TextField)):
    description = "Stores raw binary data"

    def __init__(self, *args, **kwds):
        kwds = _adjust_keywords(kwds)
        super(BlobField, self).__init__(*args, **kwds)

    def db_type(self, connection):
        if connection.vendor == 'mysql':
            return 'BLOB'
        if connection.vendor == 'oracle':
            return 'BLOB'
        if connection.vendor == 'postgresql':
            return 'bytea'
        if connection.vendor == 'sqlite':
            return 'BLOB'

    def get_internal_type(self):
        return "BlobField"

    def get_db_prep_value(self, value, connection=None, prepared=False):
        return value

    def get_db_prep_save(self, value, connection):
        if connection:
            if connection.vendor == 'oracle':
                curs = connection.cursor()
                blob = curs.var(oracle.BLOB)
                blob.setvalue(0, value)
                return blob
            if connection.vendor == 'postgresql':
                return psycopg2.Binary(value)
        return value

    def value_to_string(self, obj):
        return base64.b64encode(self._get_val_from_obj(obj))

    def to_python(self, value):
        if isinstance(value, Blob):
            return value
        if isinstance(value, basestring):
            try:
                unicode(value)
                return Blob(base64.b64decode(value))
            except UnicodeDecodeError:
                return Blob(value)
            except TypeError:
                #This field type is only used to disguise an RDKit object anyway
                #If I do this it allows me to delete the object
                return None
        return Blob(value)

