                            queue -= 1
                        j += 1
            for group in ops:
                for i in range(0, -len(tokens), -1):
                    if tokens[i] in group:
                        left = parse(tokens[:i])
                        right = parse(tokens[i+1:])
                        if type(left) == int and type(right) == int:
                            return tokens[i](left, right)
                        return (left, tokens[i], right)
