            + r'{(.+?)}|'                   # 1 label
            + r'([0-9a-f]+h|[0-9]+)|'       # 2 integer
            + r'('                          # 3 string
              + r'r"(?:\\"|.)*?(?<![^\\]\\)"|' # raw string
              + r'(?:"(?:(?<!\\)(?:\\\\)*"|.)*?(?<!\\)(?:\\\\)*")' # regular string
            + r')'
            + r')(?:\s*,)?|(?:\s*$)')
